Let's design replacement:

```
FIT_BOOL FieldBase::Read(const void *data, const FIT_UINT8 size)
{
    FIT_UINT8 bytesLeft = size;
    FIT_BYTE *byteData = (FIT_BYTE *) data;
    const FIT_UINT8 type = GetType();

    values.clear();

    if (type == FIT_BASE_TYPE_STRING)
    {
        FIT_UINT8 index = 0;
        while (index < bytesLeft && byteData[index] == 0)
            index++;
        if (index == bytesLeft)
            return FIT_TRUE;

        stringIndexes.push_back(0);

        values.reserve(values.size() + bytesLeft + 1);
        values.insert(values.end(), byteData, byteData + bytesLeft);

        for (int i = 0; i < (int)bytesLeft; ++i)
        {
            if (byteData[i] == 0 && i + 2 < (int)size)
                stringIndexes.push_back((FIT_UINT8)(i + 1));
        }

        if (values.back() != 0)
            values.push_back(0);
    }
    else
    {
        const FIT_UINT8 typeSize = baseTypeSizes[type & FIT_BASE_TYPE_NUM_MASK];
        const FIT_BYTE *invalid = baseTypeInvalids[type & FIT_BASE_TYPE_NUM_MASK];
        int bytes = bytesLeft;
        const FIT_BYTE *point = byteData;
        FIT_BOOL found = FIT_FALSE;

        switch (typeSize)
        {
            case 1:
                while (bytes > 0)
                {
                    if (*point != invalid[0]) { found = FIT_TRUE; break; }
                    point += 1;
                    bytes -= 1;
                }
                break;
            case 2:
            {
                FIT_UINT16 inv;
                memcpy(&inv, invalid, 2);
                while (bytes > 0)
                {
                    FIT_UINT16 val;
                    memcpy(&val, point, 2);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 2;
                    bytes -= 2;
                }
                break;
            }
            case 4:
            {
                FIT_UINT32 inv;
                memcpy(&inv, invalid, 4);
                while (bytes > 0)
                {
                    FIT_UINT32 val;
                    memcpy(&val, point, 4);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 4;
                    bytes -= 4;
                }
                break;
            }
            case 8:
            {
                FIT_UINT64 inv;
                memcpy(&inv, invalid, 8);
                while (bytes > 0)
                {
                    FIT_UINT64 val;
                    memcpy(&val, point, 8);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 8;
                    bytes -= 8;
                }
                break;
            }
            default:
            {
                while (bytes > 0)
                {
                    if (memcmp(point, invalid, typeSize) != 0) { found = FIT_TRUE; break; }
                    point += typeSize;
                    bytes -= typeSize;
                }
                break;
            }
        }

        if (found)
            values.insert(values.end(), byteData, byteData + bytesLeft);
    }

    return FIT_TRUE;
}
```

