FIT_BOOL FieldBase::Read(const void *data, const FIT_UINT8 size)
{
    FIT_BYTE *byteData = (FIT_BYTE *) data;
    const FIT_UINT8 type = GetType();

    if (type == FIT_BASE_TYPE_STRING)
    {
        FIT_UINT8 index = 0;
        while (index < size && byteData[index] == 0)
            ++index;
        if (index == size)
        {
            values.clear();
            return FIT_TRUE;
        }

        stringIndexes.push_back(0);

        values.reserve(size + 1);
        values.assign(byteData, byteData + size);

        for (int i = 0; i < (int)size; ++i)
        {
            if (byteData[i] == 0 && i + 2 < (int)size)
                stringIndexes.push_back((FIT_UINT8)(i + 1));
        }

        if (values.back() != 0)
            values.push_back(0);
    }
    else
    {
        const FIT_UINT8 baseType = type & FIT_BASE_TYPE_NUM_MASK;
        const FIT_UINT8 typeSize = baseTypeSizes[baseType];
        const FIT_BYTE *invalid = baseTypeInvalids[baseType];
        int bytes = size;
        const FIT_BYTE *point = byteData;
        FIT_BOOL found = FIT_FALSE;

        switch (typeSize)
        {
            case 1:
                while (bytes > 0)
                {
                    if (*point != invalid[0]) { found = FIT_TRUE; break; }
                    ++point;
                    --bytes;
                }
                break;
            case 2:
            {
                FIT_UINT16 inv;
                memcpy(&inv, invalid, 2);
                while (bytes > 0)
                {
                    FIT_UINT16 val;
                    memcpy(&val, point, 2);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 2;
                    bytes -= 2;
                }
                break;
            }
            case 4:
            {
                FIT_UINT32 inv;
                memcpy(&inv, invalid, 4);
                while (bytes > 0)
                {
                    FIT_UINT32 val;
                    memcpy(&val, point, 4);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 4;
                    bytes -= 4;
                }
                break;
            }
            case 8:
            {
                FIT_UINT64 inv;
                memcpy(&inv, invalid, 8);
                while (bytes > 0)
                {
                    FIT_UINT64 val;
                    memcpy(&val, point, 8);
                    if (val != inv) { found = FIT_TRUE; break; }
                    point += 8;
                    bytes -= 8;
                }
                break;
            }
            default:
                while (bytes > 0)
                {
                    if (memcmp(point, invalid, typeSize) != 0) { found = FIT_TRUE; break; }
                    point += typeSize;
                    bytes -= typeSize;
                }
                break;
        }

        if (found)
            values.assign(byteData, byteData + size);
        else
            values.clear();
    }

    return FIT_TRUE;
}
```

